head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > M > getValue]<br/>Multiselect 컴포넌트에 선택된 아이템들의 Value 값을 구분자로 구분한 문자열로 반환합니다.",
    "validation" : [
        "delimeter(선택) 파라미터로 선택된 아이템들의 Value 값을 구분하는 구분자를 텍스트로 설정합니다.",
        "delimeter(선택) 파라미터를 설정하지 않으면 separator 속성값이 적용됩니다.",
        "선택된 아이템들의 Value 값을 구분자가 포함된 문자열로 반환합니다.",
        "선택된 아이템이 한 개인 경우 구분자 없이 해당 아이템의 Value 값만 반환합니다.",
        "선택된 아이템이 없으면 빈 문자열('')을 반환합니다.",
        "getValue() 메소드는 선택된 아이템의 Value 값만 반환합니다.",
        "반환되는 Value 값의 순서는 컴포넌트에 정의된 아이템 순서를 따릅니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 와 바인딩, separator 속성 적용)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // separator 속성값 (con_separator 선택값)
    let cSeparator = con_separator.getText();

    let properties = {};
    if (cSeparator !== "") {
        properties.separator = cSeparator;
    }
    let cList = $c.gcm.createCList(properties);

    // 현재 적용된 separator 정보 라벨 표시
    $c.gcm.createLabel('label="target1 : separator=[' + (cSeparator === "" ? "미설정(기본 공백)" : cSeparator) + ']"', '', 'label1');

    // comp 생성 함수 호출
    $c.gcm.createBasicMultiSelect(cList);
}



// getValue(delimeter) 호출 - delimeter 인자가 separator 속성보다 우선 적용
scwin.btn_getValueDelim_onclick = function (e) {
    let delim = par_delimeter.getValue();
    let rtn = target1.getValue(delim);
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue('" + delim + "') : [" + rtn + "]");
};



// getValue() 호출 - 인자 미설정 시 separator 속성값 적용 (필수여부 N param 생략 케이스)
scwin.btn_getValue_onclick = function (e) {
    let rtn = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1.getValue() : [" + rtn + "]");
};



// 두 개 이상 선택 (인덱스 0, 2) - Value 값을 구분자로 구분한 문자열 검증용
scwin.btn_selectTwo_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(0, true);
    target1.setSelectedIndexNM(2, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 0, 2 아이템 선택 완료");
};



// 한 개만 선택 (인덱스 1) - 구분자 없이 Value 값만 반환되는지 검증용
scwin.btn_selectOne_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndexNM(1, true);
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 인덱스 1 아이템만 선택 완료");
};



// 모든 선택 해제 - 선택 없을 때 빈 문자열 반환 검증용
scwin.btn_clearSelection_onclick = function (e) {
    target1.setValue("");
    target1.setInstanceValue();
    wf_body_bottom.getObj("scwin").setReturnValue("target1 : 전체 선택 해제 완료");
};
